function decodeBasic(s) {
  return String(s || '')
    .replace(/\\\//g, '/')
    .replace(/\\u0025/g, '%')
    .replace(/\\u0026/g, '&')
    .replace(/\\u003d/g, '=')
    .replace(/\\u002F/gi, '/')
    .replace(/&amp;/g, '&')
    .replace(/&quot;/g, '"')
    .replace(/&#039;/g, "'")
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&nbsp;/g, ' ');
}

function cleanText(s) {
  return decodeBasic(s)
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<svg[\s\S]*?<\/svg>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/Ver original · Califica esta traducción/gi, '')
    .replace(/Ver original/gi, '')
    .replace(/Califica esta traducción/gi, '')
    .replace(/See translation/gi, '')
    .replace(/Rate this translation/gi, '')
    .replace(/\bLike\b|\bComment\b|\bShare\b/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function simpleHash(str) {
  str = String(str || '');
  let h1 = 0xdeadbeef;
  let h2 = 0x41c6ce57;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16) + (h1 >>> 0).toString(16)).slice(0, 24);
}

function absoluteFacebookUrl(url) {
  url = decodeBasic(url).trim();
  if (!url) return '';
  if (url.startsWith('/')) return 'https://mbasic.facebook.com' + url;
  return url;
}

function normalizePostUrl(url) {
  url = absoluteFacebookUrl(url);
  if (!url) return '';
  try {
    const u = new URL(url);
    ['__tn__','refid','ref','paipv','eav','mibextid','locale','comment_id','acontext','av'].forEach(p => u.searchParams.delete(p));
    u.hash = '';
    return u.toString();
  } catch {
    return url;
  }
}

function normalizeImageUrl(u) {
  return decodeBasic(u)
    .replace(/\\u0026/g, '&')
    .replace(/\s+/g, '')
    .trim();
}

function scoreImage(url) {
  const u = String(url || '');
  let score = 0;
  if (/scontent|fbcdn/i.test(u)) score += 8;
  if (/t39\.30808|safe_image|p960x960|p720x720|p1080x1080|_n\.(jpg|jpeg|png|webp)/i.test(u)) score += 5;
  if (/\.jpg|\.jpeg|\.png|\.webp/i.test(u)) score += 2;
  if (u.length > 180) score += 1;
  if (/p50x50|p64x64|s75x75|s100x100|emoji|sprite|icon|logo|profile|static\.xx\.fbcdn\.net|rsrc\.php/i.test(u)) score -= 12;
  return score;
}

function extractImage(block) {
  const h = decodeBasic(block);
  const candidates = [];
  let m;

  const metaRegex = /<meta[^>]+(?:property|name)=["'](?:og:image|twitter:image)["'][^>]+content=["']([^"']+)["']/gi;
  while ((m = metaRegex.exec(h)) !== null) candidates.push(m[1]);

  const imgRegex = /<img[^>]+>/gi;
  while ((m = imgRegex.exec(h)) !== null) {
    const tag = m[0];
    const src = tag.match(/\s(?:src|data-src|data-original)=["']([^"']+)["']/i)?.[1] || '';
    if (src) candidates.push(src);

    const srcset = tag.match(/\ssrcset=["']([^"']+)["']/i)?.[1] || '';
    if (srcset) {
      for (const part of srcset.split(',')) {
        const candidate = part.trim().split(/\s+/)[0];
        if (candidate) candidates.push(candidate);
      }
    }
  }

  const styleRegex = /background-image\s*:\s*url\(([^)]+)\)/gi;
  while ((m = styleRegex.exec(h)) !== null) candidates.push(m[1].replace(/^['"]|['"]$/g, ''));

  const urlRegex = /https?:\\?\/\\?\/[^"'<>\s)]+?(?:\.jpg|\.jpeg|\.png|\.webp)(?:\?[^"'<>\s)]*)?/gi;
  while ((m = urlRegex.exec(h)) !== null) candidates.push(m[0]);

  const cleaned = [...new Set(candidates.map(normalizeImageUrl))]
    .filter(Boolean)
    .filter(u => /^https?:\/\//i.test(u))
    .filter(u => scoreImage(u) > -2);

  cleaned.sort((a, b) => scoreImage(b) - scoreImage(a));
  return cleaned[0] || '';
}

function todayMadrid() {
  return new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/Madrid' });
}

function firstResult(response) {
  return response.data?.[0]?.results?.[0] || response.data?.results?.[0] || response.results?.[0] || response[0]?.results?.[0] || {};
}

function looksBlockedOnly(text, html) {
  const t = String(text || '').toLowerCase();
  const hasPostSignals = /story_fbid|\/posts\/|photo\.php|fbid=|scontent|fbcdn|abrir chatgpt|prompt|midjourney|stable diffusion|branding|logo|diseño|design/i.test(html || text || '');
  if (hasPostSignals) return false;
  return /log in|email or phone|forgot password|create new account|allow the use of cookies|cookies from facebook|cookies from other companies|join facebook or log in|inicia sesión|crear cuenta/i.test(t);
}

function usefulText(text, imageUrl, keywords) {
  const t = String(text || '');
  const loginNoiseOnly = /^(facebook|log in|join facebook|create new account|forgot password|cookies|privacy|terms|advertising|meta)+$/i.test(t.replace(/\s+/g, ' ').trim());
  if (loginNoiseOnly) return false;
  if (t.length < (imageUrl ? 25 : 60)) return false;

  const kw = String(keywords || '').split(',').map(s => s.trim()).filter(Boolean);
  const hasKeyword = kw.some(k => new RegExp(k.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'i').test(t));

  return Boolean(
    hasKeyword ||
    /prompt|chatgpt|midjourney|stable diffusion|dall[- ]?e|imagen|image|retrato|portrait|branding|logo|diseño|design|abrir chatgpt|sube tu imagen/i.test(t) ||
    imageUrl
  );
}

const browserlessItems = $input.all();
const sourceItems = $('Preparar URL Scrape').all();
const out = [];

for (let index = 0; index < browserlessItems.length; index++) {
  const item = browserlessItems[index];
  const source = sourceItems[index]?.json || {};
  const response = item.json || {};
  const result = firstResult(response);

  const fullJson = JSON.stringify(response);
  const rawText = result.text || response.text || response.data?.[0]?.text || '';
  const rawHtml = result.html || response.html || response.data?.[0]?.html || fullJson || '';
  const html = decodeBasic(rawHtml);
  const pageText = cleanText(rawText || html).slice(0, 12000);

  const base = {
    row_number: source.row_number,
    nombre: source.nombre,
    cuenta: source.nombre,
    cuenta_url: source.cuenta_url || source.url,
    url: source.url,
    original_url: source.original_url || source.url,
    scrape_url: source.scrape_url || source.url,
    tipo: source.tipo,
    activo: source.activo,
    palabras_clave: source.palabras_clave,
    ultima_revision: todayMadrid(),
    debug_text_preview: pageText.slice(0, 800),
  };

  if (!rawHtml || looksBlockedOnly(pageText, html)) {
    out.push({ json: { ...base, scrape_ok: false, post_nuevo: false, estado: 'LOGIN_O_BLOQUEO', scrape_status: 'LOGIN_O_BLOQUEO', motivo: 'Facebook devolvió login/cookies/bloqueo', scrape_motivo: 'Facebook devolvió login/cookies/bloqueo', texto_limpio: pageText.slice(0, 1000), imagen_url: '' } });
    continue;
  }

  const candidates = [];

  // 1) Bloques alrededor de enlaces de post reales.
  const linkRegex = /<a[^>]+href=["']([^"']*(?:story\.php|\/posts\/|\/photos\/|permalink\.php|\/photo\.php|fbid=)[^"']*)["'][^>]*>[\s\S]*?<\/a>/gi;
  let m;

  while ((m = linkRegex.exec(html)) !== null) {
    const postUrl = normalizePostUrl(m[1]);
    if (!postUrl) continue;

    const start = Math.max(0, m.index - 5000);
    const end = Math.min(html.length, m.index + 12000);
    const block = html.slice(start, end);
    const text = cleanText(block).slice(0, 6000);
    const imageUrl = extractImage(block);

    if (!usefulText(text, imageUrl, source.palabras_clave)) continue;

    candidates.push({
      post_url: postUrl,
      texto_limpio: text,
      imagen_url: imageUrl,
      post_hash: simpleHash(`${postUrl}|${text}|${imageUrl}`),
    });
  }

  // 2) Fallback para páginas donde mbasic no expone enlaces claros pero sí texto+imagen visibles.
  if (candidates.length === 0) {
    const imageUrl = extractImage(`${html}\n${fullJson}`);
    if (usefulText(pageText, imageUrl, source.palabras_clave)) {
      const postUrl = source.scrape_url || source.url;
      candidates.push({
        post_url: postUrl,
        texto_limpio: pageText.slice(0, 6000),
        imagen_url: imageUrl,
        post_hash: simpleHash(`${postUrl}|${pageText}|${imageUrl}`),
      });
    }
  }

  const unique = new Map();
  for (const c of candidates) {
    const key = c.post_url || c.post_hash;
    if (!unique.has(key)) unique.set(key, c);
  }

  if (unique.size === 0) {
    out.push({ json: { ...base, scrape_ok: false, post_nuevo: false, estado: 'SIN_POSTS_UTILES', scrape_status: 'SIN_POSTS_UTILES', motivo: 'No se detectaron posts útiles visibles sin login', scrape_motivo: 'No se detectaron posts útiles visibles sin login', texto_limpio: pageText.slice(0, 1000), imagen_url: extractImage(`${html}\n${fullJson}`) } });
    continue;
  }

  for (const c of unique.values()) {
    out.push({
      json: {
        ...base,
        url: c.post_url,
        post_url: c.post_url,
        post_hash: c.post_hash,
        ultimo_hash: c.post_hash,
        texto_limpio: c.texto_limpio,
        imagen_url: c.imagen_url,
        scrape_ok: true,
        scrape_status: 'OK',
        scrape_motivo: 'Post detectado',
        estado: 'OK',
        motivo: 'Post detectado',
        fecha_detectado: todayMadrid(),
      },
    });
  }
}

return out;

const j = $json;

const prompt_ia = `
Eres un analista de contenido para crear ideas de prompts de IA.

Analiza SOLO la información disponible. No inventes datos.

Cuenta: ${j.nombre || j.cuenta}
Post URL: ${j.post_url || j.url}
Página origen: ${j.cuenta_url || j.original_url || ''}
Palabras clave esperadas: ${j.palabras_clave}

Texto del post:
${j.texto_limpio}

Imagen detectada:
${j.imagen_url || 'No se detectó imagen'}

Devuelve la respuesta en Markdown con esta estructura:

# Análisis de ${j.nombre || j.cuenta}

## Resumen
Resume qué contiene este post.

## Texto / prompt detectado
Si el post incluye un prompt, extráelo completo. Si está en español, mantenlo en español.

## Estilo visual detectado
Describe la estética, composición, colores, sujeto, iluminación y detalles relevantes de la imagen si hay URL de imagen.

## Ideas de prompts
Crea 5 prompts útiles basados en el post.

## Recomendación
Di si merece la pena guardar este post en PDF: SÍ o NO, y por qué.
`.trim();

return { json: { ...j, prompt_ia } };

const ai = $json;
const base = $('Preparar prompt IA').item.json;

function getAiText(j) {
  if (typeof j === 'string') return j;
  return String(
    j.output?.text ||
    j.output ||
    j.text ||
    j.content ||
    j.message?.content ||
    j.message ||
    j.response?.content ||
    j.response ||
    j.result ||
    j.data ||
    ''
  );
}

const promptFinal = getAiText(ai).trim();

return {
  json: {
    fecha: base.fecha_detectado || base.ultima_revision,
    cuenta: base.nombre || base.cuenta,
    texto: base.texto_limpio,
    prompt: promptFinal,
    imagen_url: base.imagen_url || '',
    post_url: base.post_url || base.url,
    cuenta_url: base.cuenta_url || base.original_url || '',
    categoria: base.palabras_clave,
    exportado_pdf: 'NO',
    post_hash: base.post_hash,
    ultimo_hash: base.ultimo_hash || base.post_hash,
    url: base.post_url || base.url,
    update_url: base.cuenta_url || base.original_url || base.url,
    ultima_revision: base.ultima_revision,
  },
};

let base = {};
try { base = $('Renombrar PDF').item.json; } catch (e) {}
if (!base.update_url) { try { base = $('Preparar fila Resultado').item.json; } catch (e) {} }
if (!base.update_url) { try { base = $('Preparar prompt IA').item.json; } catch (e) {} }

return {
  json: {
    url: base.update_url || base.cuenta_url || base.original_url || base.url,
    nombre: base.cuenta || base.nombre,
    ultima_revision: base.ultima_revision || base.fecha,
    ultimo_hash: base.post_hash || base.ultimo_hash,
    estado: 'OK',
    motivo: 'Post nuevo procesado',
  },
};

const j = $json;

let estado = j.scrape_ok && !j.post_nuevo ? 'SIN_POSTS_NUEVOS' : (j.scrape_status || j.estado || 'SIN_TEXTO_UTIL');
let motivo = j.scrape_ok && !j.post_nuevo ? 'Post ya registrado en hoja Posts' : (j.scrape_motivo || j.motivo || 'No se obtuvo contenido útil');

return {
  json: {
    url: j.cuenta_url || j.original_url || j.url,
    nombre: j.nombre || j.cuenta,
    ultima_revision: j.ultima_revision,
    ultimo_hash: j.post_hash || '',
    estado,
    motivo,
  },
};

