const items = $input.all();
const htmlItems = $('Preparar HTML PDF').all();

return items.map((item, index) => {
  const meta = htmlItems[index]?.json || {};
  const filename = meta.pdf_filename || `documento_${Date.now()}.pdf`;

  item.json = {
    ...meta,
    ...item.json,
    pdf_filename: filename,
  };

  if (item.binary?.data) {
    item.binary.data.fileName = filename;
    item.binary.data.mimeType = 'application/pdf';
    item.binary.data.fileExtension = 'pdf';
  }

  return item;
});

const base = $('Preparar fila Resultado').item.json;
const j = { ...base, ...$json };

function esc(v) {
  return String(v ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const cuenta = j.cuenta || 'Sin cuenta';
const fecha = j.fecha || new Date().toISOString().slice(0, 10);

const imagenHtml = j.imagen_url
  ? `<div class="imageBox"><img src="${esc(j.imagen_url)}" /></div><p class="imgurl">Imagen: ${esc(j.imagen_url)}</p>`
  : `<div class="noImage">No se pudo extraer imagen del post.</div>`;

const html = `
<!doctype html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: Arial, sans-serif; margin: 34px; color: #222; line-height: 1.45; }
    h1 { font-size: 26px; margin-bottom: 6px; }
    h2 { font-size: 18px; margin-top: 26px; border-bottom: 1px solid #ddd; padding-bottom: 6px; }
    .meta { color: #666; font-size: 13px; margin-bottom: 22px; }
    .imageBox { text-align: center; margin: 18px 0 12px 0; page-break-inside: avoid; }
    .imageBox img { max-width: 100%; max-height: 720px; border-radius: 10px; object-fit: contain; }
    .imgurl { font-size: 10px; color: #777; overflow-wrap: anywhere; }
    .box { background: #f6f6f6; padding: 14px; border-radius: 8px; margin-bottom: 18px; white-space: pre-wrap; font-size: 14px; }
    .noImage { background: #fff4e5; padding: 12px; border-radius: 8px; color: #8a4b00; margin-bottom: 18px; }
    .small { font-size: 12px; color: #777; margin-top: 30px; }
  </style>
</head>
<body>
  <h1>${esc(cuenta)}</h1>
  <div class="meta">
    Fecha: ${esc(fecha)}<br>
    Categoría: ${esc(j.categoria)}<br>
    Post: ${esc(j.post_url)}<br>
    Página: ${esc(j.cuenta_url || '')}
  </div>

  <h2>Imagen del post</h2>
  ${imagenHtml}

  <h2>Texto del post</h2>
  <div class="box">${esc(j.texto)}</div>

  <h2>Análisis / Prompts IA</h2>
  <div class="box">${esc(j.prompt)}</div>

  <p class="small">PDF generado automáticamente desde n8n.</p>
</body>
</html>
`;

const filenameSafe = cuenta.replace(/[^a-z0-9]+/gi, '_').replace(/^_+|_+$/g, '');
const hashPart = String(j.post_hash || '').slice(0, 8);

return {
  json: {
    ...j,
    html,
    pdf_filename: `${filenameSafe || 'documento'}_${fecha}_${hashPart}.pdf`,
  },
};

const j = $json;

function normalizeFacebookUrl(url) {
  let u = String(url || '').trim();
  if (!u) return '';

  u = u.replace(/\/$/, '');

  if (/facebook\.com/i.test(u)) {
    try {
      const parsed = new URL(u);
      let path = parsed.pathname || '/';

      path = path.replace(/^\/+/, '').replace(/\/+$/, '');

      const isPost =
        /story\.php|posts|photos|videos|reel|permalink|photo\.php/i.test(path) ||
        parsed.searchParams.has('fbid');

      if (!isPost) {
        return `https://mbasic.facebook.com/${path}?v=timeline`;
      }

      return `https://mbasic.facebook.com/${path}${parsed.search || ''}`;
    } catch (e) {
      return u
        .replace(/^https?:\/\/(www\.|m\.)?facebook\.com/i, 'https://mbasic.facebook.com')
        .replace(/^https?:\/\/facebook\.com/i, 'https://mbasic.facebook.com');
    }
  }

  return u;
}

return {
  json: {
    ...j,
    scrape_url: normalizeFacebookUrl(j.url),
    debug_original_url: j.url,
    debug_scrape_url: normalizeFacebookUrl(j.url),
  },
};

const postsDetectados = $input.all();
const postsExistentes = $('Get Posts existentes').all();

const hashesExistentes = new Set();

for (const item of postsExistentes) {
  const h = String(item.json.post_hash || '').trim();
  if (h) hashesExistentes.add(h);
}

return postsDetectados.map(item => {
  const j = item.json;
  const postHash = String(j.post_hash || '').trim();

  const postNuevo = Boolean(
    j.scrape_ok === true &&
    postHash &&
    !hashesExistentes.has(postHash)
  );

  return {
    json: {
      ...j,
      post_nuevo: postNuevo,
      motivo_post_nuevo: postNuevo
        ? 'Post nuevo detectado'
        : 'Post ya existente o sin hash válido',
    },
  };
});
